import crypto from 'node:crypto';
import { Request, Response, Router } from 'express';
import { hashPasswordAsync, hashToken, normalizeEmail, verifyPasswordAsync, generateRandomToken, encryptSecret, decryptSecret } from '../auth/cryptoUtils';
import { signJwt, verifyJwt } from '../auth/jwt';
import { emailService } from '../auth/emailService';
import { realAuthRepository, RealAuthSettings, RealAuthUser } from '../auth/realAuthRepository';
import { assertSignupMailAvailable, createAndDeliverSignupVerification, SignupVerificationError } from '../auth/signupVerification';
import { controlRepository } from '../db/controlRepository';
import { redisClient } from '../redis';
import { getOAuthProvider } from '../auth/oauth';
import { generateMfaRecoveryCodes, generateTotpSecret, verifyTotpCode } from '../auth/mfa';
import { smsService } from '../auth/smsService';
import { authenticationOptions, randomChallenge, registrationOptions, verifyAuthentication, verifyRegistration } from '../auth/webauthn';
import { config } from '../config';
import { webhookEngine } from '../webhooks/webhookEngine';

export const realAuthRouter = Router();
type AuthRequest = Request & { user?: { id: string; role: string }; organizationId?: string; projectId?: string; environmentId?: string };
type Scope = { projectId:string; environmentId:string };
const reservedClaims = new Set(['sub','role','email','project_id','environment_id','session_id','iat','exp','iss','aud','token_use']);

function bodyScope(req:Request):Scope|null { const projectId=req.body?.project_id||req.headers['x-project-id'];const environmentId=req.body?.environment_id||req.headers['x-environment-id'];return typeof projectId==='string'&&typeof environmentId==='string'?{projectId,environmentId}:null; }
async function validScope(scope:Scope):Promise<boolean>{const [project,environment]=await Promise.all([controlRepository.getProject(scope.projectId),controlRepository.getEnvironment(scope.environmentId)]);return Boolean(project&&environment&&environment.project_id===project.id);}
function bearer(req:Request):string|null{const v=req.headers.authorization;return v?.startsWith('Bearer ')?v.slice(7).trim():null;}
function readCookie(req:Request,name:string):string{for(const part of String(req.headers.cookie||'').split(';')){const [key,...value]=part.trim().split('=');if(key===name)return decodeURIComponent(value.join('='));}return '';}
function send(res:Response,status:number,code:string,message:string):void{res.status(status).json({error:{code,message}});}
async function rate(key:string,limit:number,windowSeconds=60):Promise<boolean>{return(await redisClient.increment(`rate:auth:${hashToken(key)}`,windowSeconds))<=limit;}
function publicUser(user:RealAuthUser){const hidden=user.email.endsWith('@anonymous.brisabase.local')||user.email.endsWith('@phone.brisabase.local');return{id:user.id,email:hidden?'':user.email,email_verified:user.email_verified,phone:user.phone,phone_verified:Boolean(user.phone_verified),display_name:user.display_name,avatar_url:user.avatar_url,role:user.role,status:user.status,provider:user.provider,is_anonymous:Boolean(user.is_anonymous),user_metadata:user.user_metadata,custom_claims:user.custom_claims||{},created_at:user.created_at,last_sign_in_at:user.last_sign_in_at};}
function publicProvider(provider:Awaited<ReturnType<typeof realAuthRepository.getProviderConfig>>){if(!provider)return null;return{id:provider.provider,provider:provider.provider,name:provider.name,enabled:provider.enabled,client_id:provider.client_id,client_secret_configured:Boolean(provider.client_secret_encrypted),redirect_url:provider.redirect_url,updated_at:provider.updated_at};}
function passwordError(password:string,settings:RealAuthSettings):string|null{if(password.length<settings.minimum_password_length)return`Password must have at least ${settings.minimum_password_length} characters.`;if(settings.password_require_uppercase&&!/[A-Z]/.test(password))return'Password must contain an uppercase letter.';if(settings.password_require_lowercase&&!/[a-z]/.test(password))return'Password must contain a lowercase letter.';if(settings.password_require_number&&!/\d/.test(password))return'Password must contain a number.';if(settings.password_require_symbol&&!/[^A-Za-z0-9]/.test(password))return'Password must contain a symbol.';return null;}
function safeClaims(user:RealAuthUser):Record<string,unknown>{const out:Record<string,unknown>={};for(const [key,value] of Object.entries(user.custom_claims||{})){if(!reservedClaims.has(key))out[key]=value;}return out;}
function jwtFor(user:RealAuthUser,sessionId:string,settings:RealAuthSettings,extra:Record<string,unknown>={}){return signJwt({sub:user.id,project_id:user.project_id,environment_id:user.environment_id,session_id:sessionId,role:user.role,email:user.email,...safeClaims(user),app_metadata:user.app_metadata||{},user_metadata:user.user_metadata||{},...extra},settings.jwt_access_lifetime_seconds);}
const REFRESH_COOKIE='brisabase_user_refresh';
function refreshCookieOptions(){return{httpOnly:true,secure:config.cookies.secure,sameSite:config.cookies.sameSite as 'strict'|'lax'|'none',domain:config.cookies.domain,path:'/api/auth',maxAge:config.auth.jwtRefreshTokenTtlSeconds*1000};}
function setRefreshCookie(res:Response,token:string){res.cookie(REFRESH_COOKIE,token,refreshCookieOptions());}
function clearRefreshCookie(res:Response){res.clearCookie(REFRESH_COOKIE,{...refreshCookieOptions(),maxAge:undefined});}
async function issue(user:RealAuthUser,settings:RealAuthSettings,req:Request,res?:Response,method='password',mfa=false){await realAuthRepository.revokeOldestSessions(user.id,Math.max(0,settings.maximum_sessions-1));const session=await realAuthRepository.createSession({user_id:user.id,project_id:user.project_id,environment_id:user.environment_id,expires_at:new Date(Date.now()+settings.session_lifetime_seconds*1000).toISOString(),ip_address:req.ip,user_agent:req.headers['user-agent'],device_name:String(req.headers['x-device-name']||'Web browser').slice(0,255),auth_method:method,mfa_verified_at:mfa?new Date().toISOString():undefined});const refresh=generateRandomToken(32);await realAuthRepository.createRefreshToken({session_id:session.id,user_id:user.id,project_id:user.project_id,environment_id:user.environment_id,token_hash:hashToken(refresh),family_id:`fam_${crypto.randomUUID()}`,expires_at:new Date(Date.now()+settings.refresh_token_lifetime_seconds*1000).toISOString()});if(res)setRefreshCookie(res,refresh);return{access_token:jwtFor(user,session.id,settings,{amr:mfa?[method,'mfa']:[method],mfa}),refresh_token:refresh,expires_in:settings.jwt_access_lifetime_seconds,token_type:'Bearer',session_id:session.id};}
async function authUserFromToken(token:string|null,allowedUses:string[]=['access']):Promise<{payload:ReturnType<typeof verifyJwt>;user:RealAuthUser;session?:any}|null>{if(!token)return null;const payload=verifyJwt(token);const tokenUse=String(payload.token_use||'access');if(!allowedUses.includes(tokenUse))return null;const user=await realAuthRepository.findUserById(payload.sub);if(!user||user.project_id!==payload.project_id||user.environment_id!==payload.environment_id)return null;if(tokenUse==='access'){const session=await realAuthRepository.findSession(payload.session_id);if(!session||session.user_id!==user.id)return null;return{payload,user,session};}return{payload,user};}
async function audit(req:Request,user:RealAuthUser|undefined,action:string,scope?:Scope,metadata:Record<string,unknown>={}){try{const projectId=scope?.projectId||user?.project_id;if(!projectId)return;const project=await controlRepository.getProject(projectId);if(!project)return;await controlRepository.logAudit({organization_id:project.organization_id,project_id:projectId,environment_id:scope?.environmentId||user?.environment_id,user_id:user?.id||'anonymous',action,resource_type:'auth',resource_id:user?.id,metadata,ip_address:req.ip,user_agent:req.headers['user-agent']});}catch{/* auth success/failure must not depend on optional audit persistence */}}
async function emitAuthWebhook(user:RealAuthUser,eventType:string,payload:Record<string,unknown>={}){try{const project=await controlRepository.getProject(user.project_id);if(!project)return;await webhookEngine.emit({organizationId:project.organization_id,projectId:user.project_id,environmentId:user.environment_id,userId:user.id},eventType,{user:publicUser(user),...payload});}catch{/* auth success must not depend on optional webhook delivery */}}
function preauthTicket(user:RealAuthUser,use:'mfa_challenge'|'mfa_enroll'){return signJwt({sub:user.id,project_id:user.project_id,environment_id:user.environment_id,session_id:'preauth',role:user.role,email:user.email,token_use:use},300);}
function numericOtp():string{return String(crypto.randomInt(0,1_000_000)).padStart(6,'0');}
function normalizedRedirect(value:unknown,settings:RealAuthSettings):string{if(!value)return'';try{const candidate=new URL(String(value),config.appUrl);const origins=[new URL(config.appUrl).origin,...config.corsAllowedOrigins,...(Array.isArray(settings.allowed_redirect_origins)?settings.allowed_redirect_origins:[])];return origins.includes(candidate.origin)?candidate.toString():'';}catch{return'';}}
function trustedRequestOrigin(req:Request):boolean{const origin=String(req.headers.origin||'');if(!origin)return true;try{const allowed=[new URL(config.appUrl).origin,...config.corsAllowedOrigins];return allowed.includes(new URL(origin).origin);}catch{return false;}}
async function passwordlessResult(user:RealAuthUser,settings:RealAuthSettings,req:Request,res:Response,method:string){const factor=await realAuthRepository.getVerifiedMfaFactor(user.id);if(factor)return{user:publicUser(user),mfa_required:true,mfa_ticket:preauthTicket(user,'mfa_challenge')};if(settings.require_mfa)return{user:publicUser(user),mfa_enrollment_required:true,mfa_ticket:preauthTicket(user,'mfa_enroll')};return{user:publicUser(user),session:await issue(user,settings,req,res,method,false)};}
function validClaimsObject(value:unknown):value is Record<string,unknown>{return Boolean(value)&&typeof value==='object'&&!Array.isArray(value)&&Buffer.byteLength(JSON.stringify(value),'utf8')<=8192;}
async function roleAllowed(projectId:string,environmentId:string,role:string):Promise<boolean>{return['user','authenticated','admin','moderator','anonymous'].includes(role)||Boolean(await realAuthRepository.findRole(projectId,environmentId,role));}
function validateSettingsUpdate(updates:Record<string,any>):string|null{
  const bounded:Array<[string,number,number]>=[['minimum_password_length',8,128],['maximum_sessions',1,100],['session_lifetime_seconds',300,31536000],['jwt_access_lifetime_seconds',60,86400],['refresh_token_lifetime_seconds',300,31536000],['otp_lifetime_seconds',60,3600],['login_attempt_limit',1,100],['login_lockout_seconds',30,86400]];
  for(const [key,min,max] of bounded){if(updates[key]!==undefined){const value=Number(updates[key]);if(!Number.isInteger(value)||value<min||value>max)return `${key} must be an integer between ${min} and ${max}.`;updates[key]=value;}}
  const booleans=['require_email_verification','allow_signups','require_mfa','magic_link_enabled','email_otp_enabled','phone_otp_enabled','anonymous_auth_enabled','passkeys_enabled','password_require_uppercase','password_require_lowercase','password_require_number','password_require_symbol'];
  for(const key of booleans)if(updates[key]!==undefined&&typeof updates[key]!=='boolean')return `${key} must be boolean.`;
  if(updates.phone_otp_enabled===true&&!smsService.isConfigured())return 'phone_otp_enabled requires Twilio SMS configuration.';
  if(updates.allowed_redirect_origins!==undefined){if(!Array.isArray(updates.allowed_redirect_origins)||updates.allowed_redirect_origins.length>100)return 'allowed_redirect_origins must be an array with at most 100 origins.';const normalized:string[]=[];for(const value of updates.allowed_redirect_origins){try{const u=new URL(String(value));if(!['https:','http:'].includes(u.protocol))return 'allowed_redirect_origins must contain HTTP(S) origins.';normalized.push(u.origin);}catch{return 'allowed_redirect_origins must contain valid HTTP(S) origins.';}}updates.allowed_redirect_origins=[...new Set(normalized)];}
  return null;
}


// Email/password
realAuthRouter.post('/api/auth/signup',async(req,res)=>{try{const scope=bodyScope(req);if(!scope||!req.body?.email||!req.body?.password)return send(res,400,'INVALID_INPUT','email, password, project_id, and environment_id are required.');if(!await validScope(scope))return send(res,400,'INVALID_SCOPE','Project and environment scope is invalid.');if(!await rate(`signup:${req.ip}`,5,3600))return send(res,429,'RATE_LIMIT_EXCEEDED','Too many signup attempts.');const [settings,emailProvider]=await Promise.all([realAuthRepository.settings(scope.projectId,scope.environmentId),realAuthRepository.getProviderConfig(scope.projectId,scope.environmentId,'email')]);if(!emailProvider?.enabled)return send(res,403,'EMAIL_PROVIDER_DISABLED','Email/password signups are disabled.');if(!settings.allow_signups)return send(res,403,'SIGNUPS_DISABLED','New signups are disabled.');const policyError=passwordError(String(req.body.password),settings);if(policyError)return send(res,400,'WEAK_PASSWORD',policyError);const email=normalizeEmail(req.body.email);if(await realAuthRepository.findUserByEmail(scope.projectId,scope.environmentId,email))return send(res,409,'USER_EXISTS','A user with this email already exists.');if(settings.require_email_verification)await assertSignupMailAvailable(()=>emailService.healthCheck());const user=await realAuthRepository.createUser({project_id:scope.projectId,environment_id:scope.environmentId,email,email_verified:!settings.require_email_verification,display_name:req.body.display_name||email.split('@')[0],password_hash:await hashPasswordAsync(req.body.password),role:'user',status:settings.require_email_verification?'pending':'active',provider:'email',user_metadata:req.body.user_metadata||{},app_metadata:{},custom_claims:{}});await realAuthRepository.createIdentity({user_id:user.id,project_id:user.project_id,environment_id:user.environment_id,provider:'email',provider_user_id:user.id,provider_email:user.email});await audit(req,user,'auth.signup');if(settings.require_email_verification){const token=generateRandomToken(32);await createAndDeliverSignupVerification({user,token,tokenHash:hashToken(token),expiresAt:new Date(Date.now()+172800000).toISOString(),createVerificationToken:(uid,pid,eid,th,ex)=>realAuthRepository.createVerificationToken(uid,pid,eid,th,ex),sendVerificationEmail:(to,t)=>emailService.sendVerificationEmail(to,t),deleteUserInScope:(pid,eid,uid)=>realAuthRepository.deleteUserInScope(pid,eid,uid)});await emitAuthWebhook(user,'auth.user.created',{method:'email'});return void res.status(201).json({user:publicUser(user),message:'Verification email sent.'});}await emitAuthWebhook(user,'auth.user.created',{method:'email'});res.status(201).json({user:publicUser(user),session:await issue(user,settings,req,res)});}catch(error:unknown){if(error instanceof SignupVerificationError)return send(res,error.status,error.code,error.publicMessage);if(typeof error==='object'&&error&&'code'in error&&String((error as any).code)==='23505')return send(res,409,'USER_EXISTS','An account already exists for this identity.');send(res,500,'AUTH_ERROR','The account could not be created.');}});

realAuthRouter.post('/api/auth/login',async(req,res)=>{try{const scope=bodyScope(req);if(!scope||!req.body?.email||!req.body?.password)return send(res,400,'INVALID_INPUT','email, password, project_id, and environment_id are required.');if(!await validScope(scope))return send(res,400,'INVALID_SCOPE','Project and environment scope is invalid.');const settings=await realAuthRepository.settings(scope.projectId,scope.environmentId);const loginKey=`login-fail:${scope.projectId}:${scope.environmentId}:${req.ip}:${normalizeEmail(req.body.email)}`;const failures=await redisClient.get<number>(loginKey)||0;if(failures>=settings.login_attempt_limit)return send(res,429,'ACCOUNT_TEMPORARILY_LOCKED','Too many failed login attempts. Try again later.');const emailProvider=await realAuthRepository.getProviderConfig(scope.projectId,scope.environmentId,'email');if(!emailProvider?.enabled)return send(res,403,'EMAIL_PROVIDER_DISABLED','Email/password authentication is disabled.');const user=await realAuthRepository.findUserByEmail(scope.projectId,scope.environmentId,req.body.email);if(!user||!user.password_hash||!await verifyPasswordAsync(req.body.password,user.password_hash)){await redisClient.increment(loginKey,settings.login_lockout_seconds);await audit(req,undefined,'auth.login_failed',scope);return send(res,401,'INVALID_CREDENTIALS','Invalid email or password.');}await redisClient.del(loginKey);if(user.status==='disabled'||user.status==='banned')return send(res,403,'ACCOUNT_BLOCKED','This account is disabled.');if(!user.email_verified)return send(res,403,'EMAIL_NOT_VERIFIED','Verify your email before signing in.');const factor=await realAuthRepository.getVerifiedMfaFactor(user.id);if(factor||settings.require_mfa){if(!await rate(`mfa-login:${user.id}:${req.ip}`,Math.max(5,settings.login_attempt_limit),settings.login_lockout_seconds))return send(res,429,'MFA_TEMPORARILY_LOCKED','Too many MFA attempts.');if(!factor){return void res.json({mfa_enrollment_required:true,mfa_ticket:preauthTicket(user,'mfa_enroll'),user:publicUser(user)});}const code=String(req.body?.totp_code||'');const recovery=String(req.body?.recovery_code||'');const ok=code?verifyTotpCode(decryptSecret(factor.secret_encrypted),code):recovery?await realAuthRepository.consumeMfaRecoveryCode(user.id,hashToken(recovery)):false;if(!ok)return void res.json({mfa_required:true,mfa_ticket:preauthTicket(user,'mfa_challenge'),user:publicUser(user)});await realAuthRepository.touchMfaFactor(factor.id);const updated=await realAuthRepository.updateUser(user.id,{last_sign_in_at:new Date().toISOString()})||user;await audit(req,updated,'auth.login',{projectId:scope.projectId,environmentId:scope.environmentId},{mfa:true});return void res.json({user:publicUser(updated),session:await issue(updated,settings,req,res,'password',true)});}const updated=await realAuthRepository.updateUser(user.id,{last_sign_in_at:new Date().toISOString()})||user;await audit(req,updated,'auth.login');res.json({user:publicUser(updated),session:await issue(updated,settings,req,res)});}catch{send(res,500,'AUTH_ERROR','Unable to sign in.');}});

function dataPlaneIdentityMatches(payload:ReturnType<typeof verifyJwt>,session:{user_id:string;project_id:string;environment_id:string},user:RealAuthUser):boolean{return payload.token_use!=='control_plane'&&session.user_id===payload.sub&&session.project_id===payload.project_id&&session.environment_id===payload.environment_id&&user.id===payload.sub&&user.project_id===payload.project_id&&user.environment_id===payload.environment_id;}
realAuthRouter.post('/api/auth/logout',async(req,res)=>{const token=bearer(req);if(token){try{const payload=verifyJwt(token);const[session,user]=await Promise.all([realAuthRepository.findSession(payload.session_id),realAuthRepository.findUserById(payload.sub)]);if(session&&user&&dataPlaneIdentityMatches(payload,session,user))await realAuthRepository.revokeSession(session.id);}catch{}}clearRefreshCookie(res);res.json({message:'Session closed.'});});
realAuthRouter.post('/api/auth/logout-all',async(req,res)=>{try{const auth=await authUserFromToken(bearer(req));if(!auth)return send(res,401,'UNAUTHORIZED','Token is required.');const count=await realAuthRepository.revokeUserSessions(auth.user.id);clearRefreshCookie(res);await audit(req,auth.user,'auth.logout_all');res.json({message:`Revoked ${count} sessions.`});}catch{send(res,401,'INVALID_TOKEN','Invalid or expired token.');}});
realAuthRouter.get('/api/auth/user',async(req,res)=>{try{const auth=await authUserFromToken(bearer(req));if(!auth||auth.user.status!=='active')return send(res,401,'SESSION_REVOKED','Session is no longer valid.');await realAuthRepository.touchSession(auth.session.id);const [identities,passkeys]=await Promise.all([realAuthRepository.listIdentities(auth.user.id),realAuthRepository.listPasskeys(auth.user.id)]);res.json({...publicUser(auth.user),identities:identities.map(x=>({provider:x.provider,provider_user_id:x.provider_user_id,created_at:x.created_at})),passkeys:passkeys.map(x=>({id:x.id,device_name:x.device_name,created_at:x.created_at,last_used_at:x.last_used_at}))});}catch{send(res,401,'INVALID_TOKEN','Invalid or expired token.');}});
realAuthRouter.delete('/api/auth/identities/:identityId',async(req,res)=>{try{const auth=await authUserFromToken(bearer(req));if(!auth)return send(res,401,'UNAUTHORIZED','Authentication is required.');const identity=await realAuthRepository.findIdentityById(auth.user.id,req.params.identityId);if(!identity)return send(res,404,'IDENTITY_NOT_FOUND','Identity not found.');if(identity.provider==='email')return send(res,400,'PRIMARY_IDENTITY','The email identity cannot be unlinked from this endpoint.');const deleted=await realAuthRepository.deleteIdentity(auth.user.id,identity.id);if(!deleted)return send(res,404,'IDENTITY_NOT_FOUND','Identity not found.');await audit(req,auth.user,'auth.identity_unlinked',undefined,{provider:identity.provider});res.status(204).end();}catch{send(res,400,'IDENTITY_UNLINK_FAILED','Unable to unlink identity.');}});

realAuthRouter.post('/api/auth/refresh',async(req,res)=>{try{const bodyRefresh=String(req.body?.refresh_token||'');const cookieRefresh=readCookie(req,REFRESH_COOKIE);if(!bodyRefresh&&cookieRefresh&&!trustedRequestOrigin(req))return send(res,403,'INVALID_ORIGIN','Refresh cookie cannot be used from this origin.');const raw=bodyRefresh||cookieRefresh;if(!raw)return send(res,400,'INVALID_INPUT','refresh_token is required.');const tokenHash=hashToken(raw);const refresh=await realAuthRepository.findRefreshToken(tokenHash);if(!refresh){const reused=await realAuthRepository.findRefreshTokenAny(tokenHash);if(reused?.family_id){await realAuthRepository.revokeRefreshFamily(reused.family_id);if(reused.user_id)await realAuthRepository.revokeUserSessions(reused.user_id);await audit(req,reused.user_id?await realAuthRepository.findUserById(reused.user_id)||undefined:undefined,'auth.refresh_reuse_detected');}return send(res,401,'INVALID_REFRESH_TOKEN','Invalid or expired refresh token.');}const[session,user,settings]=await Promise.all([realAuthRepository.findSession(refresh.session_id),realAuthRepository.findUserById(refresh.user_id),realAuthRepository.settings(refresh.project_id,refresh.environment_id)]);if(!session||!user||user.status!=='active'||session.user_id!==refresh.user_id||session.project_id!==refresh.project_id||session.environment_id!==refresh.environment_id||user.project_id!==refresh.project_id||user.environment_id!==refresh.environment_id){await realAuthRepository.revokeRefreshFamily(refresh.family_id);return send(res,401,'SESSION_EXPIRED','Session is no longer active.');}await realAuthRepository.revokeRefreshToken(refresh.id);const next=generateRandomToken(32);await realAuthRepository.createRefreshToken({session_id:session.id,user_id:user.id,project_id:user.project_id,environment_id:user.environment_id,token_hash:hashToken(next),family_id:refresh.family_id,expires_at:new Date(Date.now()+settings.refresh_token_lifetime_seconds*1000).toISOString()});setRefreshCookie(res,next);res.json({access_token:jwtFor(user,session.id,settings,{amr:[session.auth_method||'refresh'],mfa:Boolean(session.mfa_verified_at)}),refresh_token:next,expires_in:settings.jwt_access_lifetime_seconds,token_type:'Bearer'});}catch{send(res,401,'INVALID_REFRESH_TOKEN','Invalid or expired refresh token.');}});

// Verification and password lifecycle
realAuthRouter.post('/api/auth/verify-email',async(req,res)=>{try{if(!req.body?.token)return send(res,400,'INVALID_INPUT','Verification token is required.');const record=await realAuthRepository.consumeVerificationToken(hashToken(req.body.token));if(!record)return send(res,400,'INVALID_OR_EXPIRED_TOKEN','Invalid or expired verification token.');const user=await realAuthRepository.updateUser(record.user_id,{email_verified:true,status:'active'});if(user)await audit(req,user,'auth.email_verified');res.json({message:'Email verified.'});}catch{send(res,400,'INVALID_OR_EXPIRED_TOKEN','Invalid or expired verification token.');}});
realAuthRouter.post('/api/auth/resend-verification',async(req,res)=>{try{const scope=bodyScope(req);if(scope&&req.body?.email&&await rate(`verify:${scope.projectId}:${req.ip}`,5,3600)){const user=await realAuthRepository.findUserByEmail(scope.projectId,scope.environmentId,req.body.email);if(user&&!user.email_verified){const token=generateRandomToken(32);await realAuthRepository.createVerificationToken(user.id,user.project_id,user.environment_id,hashToken(token),new Date(Date.now()+172800000).toISOString());await emailService.sendVerificationEmail(user.email,token);}}res.json({message:'If the account exists, a verification email was sent.'});}catch{res.json({message:'If the account exists, a verification email was sent.'});}});
realAuthRouter.post('/api/auth/password-reset/request',async(req,res)=>{try{const scope=bodyScope(req);if(scope&&req.body?.email&&await rate(`reset:${scope.projectId}:${req.ip}`,5,3600)){const user=await realAuthRepository.findUserByEmail(scope.projectId,scope.environmentId,req.body.email);if(user&&!user.is_anonymous){const token=generateRandomToken(32);await realAuthRepository.createPasswordResetToken(user.id,user.project_id,user.environment_id,hashToken(token),new Date(Date.now()+3600000).toISOString());await emailService.sendPasswordResetEmail(user.email,token);}}res.json({message:'If the account exists, reset instructions were sent.'});}catch{res.json({message:'If the account exists, reset instructions were sent.'});}});
realAuthRouter.post('/api/auth/password-reset/confirm',async(req,res)=>{try{if(!req.body?.token||!req.body?.new_password)return send(res,400,'INVALID_INPUT','token and new_password are required.');const tokenHash=hashToken(String(req.body.token));const preview=await realAuthRepository.findPasswordResetToken(tokenHash);if(!preview)return send(res,400,'INVALID_OR_EXPIRED_TOKEN','Invalid or expired reset token.');const settings=await realAuthRepository.settings(preview.project_id,preview.environment_id);const policyError=passwordError(String(req.body.new_password),settings);if(policyError)return send(res,400,'WEAK_PASSWORD',policyError);const record=await realAuthRepository.consumePasswordResetToken(tokenHash);if(!record)return send(res,409,'TOKEN_ALREADY_USED','Reset token was already consumed.');const user=await realAuthRepository.updateUser(record.user_id,{password_hash:await hashPasswordAsync(req.body.new_password)});await realAuthRepository.revokeUserSessions(record.user_id);if(user)await audit(req,user,'auth.password_reset');res.json({message:'Password reset completed.'});}catch{send(res,400,'INVALID_OR_EXPIRED_TOKEN','Invalid or expired reset token.');}});
realAuthRouter.post('/api/auth/password/change',async(req,res)=>{try{const auth=await authUserFromToken(bearer(req));if(!auth||!req.body?.current_password||!req.body?.new_password)return send(res,401,'UNAUTHORIZED','Authenticated session and both passwords are required.');if(!auth.user.password_hash||!await verifyPasswordAsync(String(req.body.current_password),auth.user.password_hash))return send(res,401,'INVALID_CREDENTIALS','Current password is invalid.');const settings=await realAuthRepository.settings(auth.user.project_id,auth.user.environment_id);const policyError=passwordError(String(req.body.new_password),settings);if(policyError)return send(res,400,'WEAK_PASSWORD',policyError);await realAuthRepository.updateUser(auth.user.id,{password_hash:await hashPasswordAsync(req.body.new_password)});await realAuthRepository.revokeUserSessionsExcept(auth.user.id,auth.payload.session_id);await audit(req,auth.user,'auth.password_changed');res.json({message:'Password changed.'});}catch{send(res,400,'PASSWORD_CHANGE_FAILED','Unable to change password.');}});

// Magic link and OTP
async function ensureEmailUser(scope:Scope,email:string):Promise<RealAuthUser|null>{let user=await realAuthRepository.findUserByEmail(scope.projectId,scope.environmentId,email);if(user)return user;const settings=await realAuthRepository.settings(scope.projectId,scope.environmentId);if(!settings.allow_signups)return null;user=await realAuthRepository.createUser({project_id:scope.projectId,environment_id:scope.environmentId,email,email_verified:false,display_name:email.split('@')[0],role:'user',status:'pending',provider:'email',user_metadata:{},app_metadata:{},custom_claims:{}});await realAuthRepository.createIdentity({user_id:user.id,project_id:scope.projectId,environment_id:scope.environmentId,provider:'email',provider_user_id:user.id,provider_email:email});return user;}
realAuthRouter.post('/api/auth/magic-link/request',async(req,res)=>{try{const scope=bodyScope(req);if(!scope||!req.body?.email)return send(res,400,'INVALID_INPUT','email, project_id, and environment_id are required.');if(!await validScope(scope))return send(res,400,'INVALID_SCOPE','Project and environment scope is invalid.');const settings=await realAuthRepository.settings(scope.projectId,scope.environmentId);if(!settings.magic_link_enabled)return send(res,403,'MAGIC_LINK_DISABLED','Magic Link is disabled.');if(await rate(`magic:${scope.projectId}:${req.ip}`,5,3600)){const email=normalizeEmail(req.body.email);const user=await ensureEmailUser(scope,email);if(user){const token=generateRandomToken(32);const redirect=normalizedRedirect(req.body.redirect_url,settings);await realAuthRepository.createOneTimeCode({project_id:scope.projectId,environment_id:scope.environmentId,user_id:user.id,purpose:'magic_link',destination:email,code_hash:hashToken(token),redirect_url:redirect,expires_at:new Date(Date.now()+settings.otp_lifetime_seconds*1000).toISOString(),max_attempts:1});const link=`${config.appUrl.replace(/\/$/,'')}/auth/v1/magic-link?project_id=${encodeURIComponent(scope.projectId)}&environment_id=${encodeURIComponent(scope.environmentId)}&email=${encodeURIComponent(email)}&token=${encodeURIComponent(token)}`;await emailService.sendEmail({to:email,subject:'Seu link de acesso — BrisaBase',body:`Use este link para entrar: ${link}`,html:`<p><a href="${link}">Entrar com BrisaBase</a></p>`});}}res.json({message:'If the account can use Magic Link, a sign-in email was sent.'});}catch{res.json({message:'If the account can use Magic Link, a sign-in email was sent.'});}});
realAuthRouter.post('/api/auth/magic-link/verify',async(req,res)=>{try{const scope=bodyScope(req);const email=normalizeEmail(String(req.body?.email||''));if(!scope||!email||!req.body?.token)return send(res,400,'INVALID_INPUT','email, token, project_id, and environment_id are required.');if(!await validScope(scope))return send(res,400,'INVALID_SCOPE','Project and environment scope is invalid.');const record=await realAuthRepository.consumeOneTimeCode(scope.projectId,scope.environmentId,'magic_link',email,hashToken(String(req.body.token)));if(!record?.user_id)return send(res,400,'INVALID_OR_EXPIRED_TOKEN','Magic Link is invalid or expired.');let user=await realAuthRepository.findUserById(record.user_id);if(!user)return send(res,400,'INVALID_OR_EXPIRED_TOKEN','Magic Link is invalid or expired.');user=await realAuthRepository.updateUser(user.id,{email_verified:true,status:'active',last_sign_in_at:new Date().toISOString()})||user;const settings=await realAuthRepository.settings(scope.projectId,scope.environmentId);await audit(req,user,'auth.magic_link');res.json({...await passwordlessResult(user,settings,req,res,'magic_link'),redirect_url:record.redirect_url||undefined});}catch{send(res,400,'INVALID_OR_EXPIRED_TOKEN','Magic Link is invalid or expired.');}});
realAuthRouter.post('/api/auth/email-otp/request',async(req,res)=>{try{const scope=bodyScope(req);if(!scope||!req.body?.email)return send(res,400,'INVALID_INPUT','email and scope are required.');if(!await validScope(scope))return send(res,400,'INVALID_SCOPE','Project and environment scope is invalid.');const settings=await realAuthRepository.settings(scope.projectId,scope.environmentId);if(!settings.email_otp_enabled)return send(res,403,'EMAIL_OTP_DISABLED','Email OTP is disabled.');if(await rate(`email-otp:${scope.projectId}:${req.ip}`,6,3600)){const email=normalizeEmail(req.body.email);const user=await ensureEmailUser(scope,email);if(user){const code=numericOtp();await realAuthRepository.createOneTimeCode({project_id:scope.projectId,environment_id:scope.environmentId,user_id:user.id,purpose:'email_otp',destination:email,code_hash:hashToken(code),expires_at:new Date(Date.now()+settings.otp_lifetime_seconds*1000).toISOString()});await emailService.sendEmail({to:email,subject:'Código de acesso — BrisaBase',body:`Seu código BrisaBase é ${code}.`,html:`<p>Seu código BrisaBase é <strong>${code}</strong>.</p>`});}}res.json({message:'If the account can use email OTP, a code was sent.'});}catch{res.json({message:'If the account can use email OTP, a code was sent.'});}});
realAuthRouter.post('/api/auth/email-otp/verify',async(req,res)=>{try{const scope=bodyScope(req);const email=normalizeEmail(String(req.body?.email||''));if(!scope||!email||!req.body?.code)return send(res,400,'INVALID_INPUT','email, code, and scope are required.');if(!await validScope(scope))return send(res,400,'INVALID_SCOPE','Project and environment scope is invalid.');const record=await realAuthRepository.consumeOneTimeCode(scope.projectId,scope.environmentId,'email_otp',email,hashToken(String(req.body.code)));if(!record?.user_id)return send(res,400,'INVALID_OTP','Invalid or expired OTP.');let user=await realAuthRepository.findUserById(record.user_id);if(!user)return send(res,400,'INVALID_OTP','Invalid or expired OTP.');user=await realAuthRepository.updateUser(user.id,{email_verified:true,status:'active',last_sign_in_at:new Date().toISOString()})||user;const settings=await realAuthRepository.settings(scope.projectId,scope.environmentId);await audit(req,user,'auth.email_otp');res.json(await passwordlessResult(user,settings,req,res,'email_otp'));}catch{send(res,400,'INVALID_OTP','Invalid or expired OTP.');}});
realAuthRouter.post('/api/auth/phone-otp/request',async(req,res)=>{try{const scope=bodyScope(req);if(!scope||!req.body?.phone)return send(res,400,'INVALID_INPUT','phone and scope are required.');if(!await validScope(scope))return send(res,400,'INVALID_SCOPE','Project and environment scope is invalid.');const settings=await realAuthRepository.settings(scope.projectId,scope.environmentId);if(!settings.phone_otp_enabled)return send(res,403,'PHONE_OTP_DISABLED','Phone OTP is disabled.');if(!smsService.isConfigured())return send(res,503,'SMS_NOT_CONFIGURED','SMS delivery is not configured.');const phone=smsService.normalize(req.body.phone);if(await rate(`phone-otp:${scope.projectId}:${req.ip}`,6,3600)){let user=await realAuthRepository.findUserByPhone(scope.projectId,scope.environmentId,phone);if(!user&&settings.allow_signups){const synthetic=`phone_${hashToken(phone).slice(0,24)}@phone.brisabase.local`;user=await realAuthRepository.createUser({project_id:scope.projectId,environment_id:scope.environmentId,email:synthetic,email_verified:true,phone,phone_verified:false,display_name:phone,role:'user',status:'pending',provider:'phone',user_metadata:{},app_metadata:{},custom_claims:{}});}if(user){const code=numericOtp();await realAuthRepository.createOneTimeCode({project_id:scope.projectId,environment_id:scope.environmentId,user_id:user.id,purpose:'phone_otp',destination:phone,code_hash:hashToken(code),expires_at:new Date(Date.now()+settings.otp_lifetime_seconds*1000).toISOString()});await smsService.sendOtp(phone,code);}}res.json({message:'If the phone can be authenticated, a code was sent.'});}catch(error){send(res,400,'PHONE_OTP_FAILED',error instanceof Error?error.message:'Phone OTP request failed.');}});
realAuthRouter.post('/api/auth/phone-otp/verify',async(req,res)=>{try{const scope=bodyScope(req);if(!scope||!req.body?.phone||!req.body?.code)return send(res,400,'INVALID_INPUT','phone, code, and scope are required.');if(!await validScope(scope))return send(res,400,'INVALID_SCOPE','Project and environment scope is invalid.');const phone=smsService.normalize(req.body.phone);const record=await realAuthRepository.consumeOneTimeCode(scope.projectId,scope.environmentId,'phone_otp',phone,hashToken(String(req.body.code)));if(!record?.user_id)return send(res,400,'INVALID_OTP','Invalid or expired OTP.');let user=await realAuthRepository.findUserById(record.user_id);if(!user)return send(res,400,'INVALID_OTP','Invalid or expired OTP.');user=await realAuthRepository.updatePhone(user.id,phone,true)||user;user=await realAuthRepository.updateUser(user.id,{status:'active',last_sign_in_at:new Date().toISOString()})||user;const settings=await realAuthRepository.settings(scope.projectId,scope.environmentId);await audit(req,user,'auth.phone_otp');res.json(await passwordlessResult(user,settings,req,res,'phone_otp'));}catch{send(res,400,'INVALID_OTP','Invalid or expired OTP.');}});
realAuthRouter.post('/api/auth/anonymous',async(req,res)=>{try{const scope=bodyScope(req);if(!scope||!await validScope(scope))return send(res,400,'INVALID_SCOPE','Project and environment scope is invalid.');const settings=await realAuthRepository.settings(scope.projectId,scope.environmentId);if(!settings.anonymous_auth_enabled)return send(res,403,'ANONYMOUS_AUTH_DISABLED','Anonymous authentication is disabled.');if(!await rate(`anonymous:${scope.projectId}:${req.ip}`,20,3600))return send(res,429,'RATE_LIMIT_EXCEEDED','Too many anonymous sessions.');const marker=crypto.randomUUID().replace(/-/g,'');const user=await realAuthRepository.createUser({project_id:scope.projectId,environment_id:scope.environmentId,email:`anon_${marker}@anonymous.brisabase.local`,email_verified:true,display_name:'Anonymous user',role:'user',status:'active',provider:'anonymous',is_anonymous:true,user_metadata:{},app_metadata:{},custom_claims:{}});await audit(req,user,'auth.anonymous_created');await emitAuthWebhook(user,'auth.user.created',{method:'anonymous'});res.status(201).json({user:publicUser(user),session:await issue(user,settings,req,res,'anonymous')});}catch{send(res,500,'AUTH_ERROR','Unable to create anonymous session.');}});
realAuthRouter.post('/api/auth/anonymous/convert',async(req,res)=>{try{const auth=await authUserFromToken(bearer(req));if(!auth||!auth.user.is_anonymous)return send(res,401,'ANONYMOUS_SESSION_REQUIRED','An anonymous authenticated session is required.');const email=normalizeEmail(String(req.body?.email||''));const password=String(req.body?.password||'');if(!email||!password)return send(res,400,'INVALID_INPUT','email and password are required.');const settings=await realAuthRepository.settings(auth.user.project_id,auth.user.environment_id);const policyError=passwordError(password,settings);if(policyError)return send(res,400,'WEAK_PASSWORD',policyError);if(await realAuthRepository.findUserByEmail(auth.user.project_id,auth.user.environment_id,email))return send(res,409,'USER_EXISTS','A user with this email already exists.');const converted=await realAuthRepository.convertAnonymousUser(auth.user.id,email,await hashPasswordAsync(password),String(req.body?.display_name||''));if(!converted)return send(res,409,'ANONYMOUS_CONVERSION_FAILED','Anonymous account could not be converted.');await realAuthRepository.createIdentity({user_id:converted.id,project_id:converted.project_id,environment_id:converted.environment_id,provider:'email',provider_user_id:converted.id,provider_email:converted.email});const token=generateRandomToken(32);await realAuthRepository.createVerificationToken(converted.id,converted.project_id,converted.environment_id,hashToken(token),new Date(Date.now()+172800000).toISOString());await emailService.sendVerificationEmail(converted.email,token);await audit(req,converted,'auth.anonymous_converted');await emitAuthWebhook(converted,'auth.user.updated',{reason:'anonymous_converted'});await realAuthRepository.revokeUserSessionsExcept(converted.id,auth.payload.session_id);res.json({user:publicUser(converted),message:'Account converted. Verify the new email before the next login.'});}catch{send(res,400,'ANONYMOUS_CONVERSION_FAILED','Unable to convert anonymous account.');}});

// MFA
realAuthRouter.post('/api/auth/mfa/challenge',async(req,res)=>{try{const auth=await authUserFromToken(String(req.body?.mfa_ticket||''),['mfa_challenge']);if(!auth)return send(res,401,'INVALID_MFA_TICKET','MFA ticket is invalid or expired.');const settings=await realAuthRepository.settings(auth.user.project_id,auth.user.environment_id);if(!await rate(`mfa-challenge:${auth.user.id}:${req.ip}`,Math.max(5,settings.login_attempt_limit),settings.login_lockout_seconds))return send(res,429,'MFA_TEMPORARILY_LOCKED','Too many MFA attempts.');const factor=await realAuthRepository.getVerifiedMfaFactor(auth.user.id);if(!factor)return send(res,400,'MFA_NOT_ENROLLED','No verified MFA factor exists.');const code=String(req.body?.code||'');const recovery=String(req.body?.recovery_code||'');const ok=code?verifyTotpCode(decryptSecret(factor.secret_encrypted),code):recovery?await realAuthRepository.consumeMfaRecoveryCode(auth.user.id,hashToken(recovery)):false;if(!ok)return send(res,401,'INVALID_MFA_CODE','MFA code is invalid.');await realAuthRepository.touchMfaFactor(factor.id);const user=await realAuthRepository.updateUser(auth.user.id,{last_sign_in_at:new Date().toISOString()})||auth.user;await audit(req,user,'auth.mfa_challenge');res.json({user:publicUser(user),session:await issue(user,settings,req,res,'password',true)});}catch{send(res,401,'INVALID_MFA_CODE','MFA verification failed.');}});
async function mfaEnrollmentActor(req:Request){return authUserFromToken(bearer(req)||String(req.body?.mfa_ticket||''),['access','mfa_enroll']);}
realAuthRouter.post('/api/auth/mfa/enroll',async(req,res)=>{try{const auth=await mfaEnrollmentActor(req);if(!auth)return send(res,401,'UNAUTHORIZED','An authenticated or MFA enrollment session is required.');await realAuthRepository.deletePendingMfaFactors(auth.user.id);const generated=generateTotpSecret();const factor=await realAuthRepository.createMfaFactor(auth.user.id,auth.user.project_id,auth.user.environment_id,'totp',encryptSecret(generated.secret));res.json({factor_id:factor.id,secret:generated.secret,otpauth_url:generated.otpauthUrl.replace('BrisaBase?',`BrisaBase:${encodeURIComponent(auth.user.email)}?`)});}catch{send(res,400,'MFA_ENROLL_FAILED','Unable to enroll MFA.');}});
realAuthRouter.post('/api/auth/mfa/verify',async(req,res)=>{try{const auth=await mfaEnrollmentActor(req);if(!auth||!req.body?.code)return send(res,401,'UNAUTHORIZED','MFA enrollment session and code are required.');if(!await rate(`mfa-enroll:${auth.user.id}:${req.ip}`,10,900))return send(res,429,'MFA_TEMPORARILY_LOCKED','Too many MFA attempts.');const factor=await realAuthRepository.getPendingMfaFactor(auth.user.id);if(!factor||!verifyTotpCode(decryptSecret(factor.secret_encrypted),String(req.body.code)))return send(res,400,'INVALID_MFA_CODE','MFA code is invalid.');await realAuthRepository.verifyMfaFactor(factor.id);await realAuthRepository.deleteOtherMfaFactors(auth.user.id,factor.id);const recovery=generateMfaRecoveryCodes(10);await realAuthRepository.replaceMfaRecoveryCodes(auth.user.id,factor.id,recovery.hashedCodes);await audit(req,auth.user,'auth.mfa_enabled');const response:any={message:'MFA enabled.',recovery_codes:recovery.rawCodes};if(auth.payload.token_use==='mfa_enroll'){const settings=await realAuthRepository.settings(auth.user.project_id,auth.user.environment_id);response.user=publicUser(auth.user);response.session=await issue(auth.user,settings,req,res,'password',true);}res.json(response);}catch{send(res,400,'MFA_VERIFY_FAILED','Unable to verify MFA enrollment.');}});
realAuthRouter.post('/api/auth/mfa/disable',async(req,res)=>{try{const auth=await authUserFromToken(bearer(req));if(!auth)return send(res,401,'UNAUTHORIZED','Authentication is required.');const factor=await realAuthRepository.getVerifiedMfaFactor(auth.user.id);if(!factor)return send(res,400,'MFA_NOT_ENROLLED','MFA is not enabled.');const code=String(req.body?.code||'');const recovery=String(req.body?.recovery_code||'');const ok=code?verifyTotpCode(decryptSecret(factor.secret_encrypted),code):recovery?await realAuthRepository.consumeMfaRecoveryCode(auth.user.id,hashToken(recovery)):false;if(!ok)return send(res,401,'INVALID_MFA_CODE','A current MFA code is required.');await realAuthRepository.deleteMfaFactors(auth.user.id);await realAuthRepository.revokeUserSessionsExcept(auth.user.id,auth.payload.session_id);await audit(req,auth.user,'auth.mfa_disabled');res.json({message:'MFA disabled.'});}catch{send(res,400,'MFA_DISABLE_FAILED','Unable to disable MFA.');}});
realAuthRouter.post('/api/auth/mfa/recovery-codes',async(req,res)=>{try{const auth=await authUserFromToken(bearer(req));if(!auth)return send(res,401,'UNAUTHORIZED','Authentication is required.');const factor=await realAuthRepository.getVerifiedMfaFactor(auth.user.id);if(!factor||!verifyTotpCode(decryptSecret(factor.secret_encrypted),String(req.body?.code||'')))return send(res,401,'INVALID_MFA_CODE','A current TOTP code is required.');const recovery=generateMfaRecoveryCodes(10);await realAuthRepository.replaceMfaRecoveryCodes(auth.user.id,factor.id,recovery.hashedCodes);await audit(req,auth.user,'auth.mfa_recovery_codes_rotated');res.json({recovery_codes:recovery.rawCodes});}catch{send(res,400,'MFA_RECOVERY_FAILED','Unable to rotate recovery codes.');}});

// Passkeys / WebAuthn
realAuthRouter.post('/api/auth/passkeys/register/options',async(req,res)=>{try{const auth=await authUserFromToken(bearer(req)||String(req.body?.mfa_ticket||''),['access','mfa_enroll']);if(!auth)return send(res,401,'UNAUTHORIZED','Authentication is required.');const settings=await realAuthRepository.settings(auth.user.project_id,auth.user.environment_id);if(!settings.passkeys_enabled)return send(res,403,'PASSKEYS_DISABLED','Passkeys are disabled.');const challenge=randomChallenge();const passkeys=await realAuthRepository.listPasskeys(auth.user.id);const flowId=generateRandomToken(18);await redisClient.set(`passkey:register:${hashToken(flowId)}`,{challenge,userId:auth.user.id,projectId:auth.user.project_id,environmentId:auth.user.environment_id,preauth:auth.payload.token_use==='mfa_enroll'},300);res.json({flow_id:flowId,public_key:registrationOptions({id:auth.user.id,email:auth.user.email,displayName:auth.user.display_name},challenge,passkeys.map(x=>x.credential_id))});}catch{send(res,400,'PASSKEY_REGISTRATION_FAILED','Unable to start passkey registration.');}});
realAuthRouter.post('/api/auth/passkeys/register/verify',async(req,res)=>{try{const flowId=String(req.body?.flow_id||'');const flow=await redisClient.get<any>(`passkey:register:${hashToken(flowId)}`);if(!flow)return send(res,400,'PASSKEY_FLOW_EXPIRED','Passkey registration flow expired.');await redisClient.del(`passkey:register:${hashToken(flowId)}`);const user=await realAuthRepository.findUserById(flow.userId);if(!user||user.project_id!==flow.projectId||user.environment_id!==flow.environmentId)return send(res,400,'PASSKEY_FLOW_INVALID','Passkey registration scope is invalid.');const verified=verifyRegistration(req.body?.credential,flow.challenge);const passkey=await realAuthRepository.createPasskey({user_id:user.id,project_id:user.project_id,environment_id:user.environment_id,credential_id:verified.credentialId,public_key_jwk:verified.publicKeyJwk,sign_count:verified.signCount,transports:verified.transports,device_name:String(req.body?.device_name||'Passkey').slice(0,255)});await audit(req,user,'auth.passkey_registered');const response:any={passkey:{id:passkey.id,device_name:passkey.device_name,created_at:passkey.created_at}};if(flow.preauth){const settings=await realAuthRepository.settings(user.project_id,user.environment_id);response.user=publicUser(user);response.session=await issue(user,settings,req,res,'passkey',true);}res.status(201).json(response);}catch(error){send(res,400,'PASSKEY_REGISTRATION_FAILED',error instanceof Error?error.message:'Passkey registration failed.');}});
realAuthRouter.post('/api/auth/passkeys/authenticate/options',async(req,res)=>{try{const scope=bodyScope(req);if(!scope||!await validScope(scope))return send(res,400,'INVALID_SCOPE','Project and environment scope is invalid.');if(!await rate(`passkey-auth:${scope.projectId}:${req.ip}`,30,3600))return send(res,429,'RATE_LIMIT_EXCEEDED','Too many passkey authentication attempts.');const settings=await realAuthRepository.settings(scope.projectId,scope.environmentId);if(!settings.passkeys_enabled)return send(res,403,'PASSKEYS_DISABLED','Passkeys are disabled.');let user:RealAuthUser|null=null;let passkeys:any[]=[];if(req.body?.email){user=await realAuthRepository.findUserByEmail(scope.projectId,scope.environmentId,req.body.email);if(user)passkeys=await realAuthRepository.listPasskeys(user.id);}const challenge=randomChallenge();const flowId=generateRandomToken(18);await redisClient.set(`passkey:auth:${hashToken(flowId)}`,{challenge,projectId:scope.projectId,environmentId:scope.environmentId,userId:user?.id},300);res.json({flow_id:flowId,public_key:authenticationOptions(challenge,passkeys.map(x=>x.credential_id))});}catch{send(res,400,'PASSKEY_AUTH_FAILED','Unable to start passkey authentication.');}});
realAuthRouter.post('/api/auth/passkeys/authenticate/verify',async(req,res)=>{try{const flowId=String(req.body?.flow_id||'');const flow=await redisClient.get<any>(`passkey:auth:${hashToken(flowId)}`);if(!flow)return send(res,400,'PASSKEY_FLOW_EXPIRED','Passkey authentication flow expired.');await redisClient.del(`passkey:auth:${hashToken(flowId)}`);const credentialId=String(req.body?.credential?.id||'');const passkey=await realAuthRepository.findPasskey(flow.projectId,flow.environmentId,credentialId);if(!passkey||flow.userId&&passkey.user_id!==flow.userId)return send(res,401,'PASSKEY_INVALID','Passkey is not valid for this user.');const nextCounter=verifyAuthentication(req.body.credential,flow.challenge,{credentialId:passkey.credential_id,publicKeyJwk:passkey.public_key_jwk,signCount:Number(passkey.sign_count)});await realAuthRepository.updatePasskeyCounter(passkey.id,nextCounter);const user=await realAuthRepository.findUserById(passkey.user_id);if(!user||user.status!=='active')return send(res,403,'ACCOUNT_BLOCKED','Account is unavailable.');const settings=await realAuthRepository.settings(user.project_id,user.environment_id);const updated=await realAuthRepository.updateUser(user.id,{last_sign_in_at:new Date().toISOString()})||user;await audit(req,updated,'auth.passkey_login');res.json({user:publicUser(updated),session:await issue(updated,settings,req,res,'passkey',true)});}catch(error){send(res,401,'PASSKEY_INVALID',error instanceof Error?error.message:'Passkey authentication failed.');}});
realAuthRouter.get('/api/auth/passkeys',async(req,res)=>{try{const auth=await authUserFromToken(bearer(req));if(!auth)return send(res,401,'UNAUTHORIZED','Authentication is required.');const rows=await realAuthRepository.listPasskeys(auth.user.id);res.json(rows.map(x=>({id:x.id,device_name:x.device_name,transports:x.transports,created_at:x.created_at,last_used_at:x.last_used_at})));}catch{send(res,401,'UNAUTHORIZED','Authentication is required.');}});
realAuthRouter.delete('/api/auth/passkeys/:passkeyId',async(req,res)=>{try{const auth=await authUserFromToken(bearer(req));if(!auth)return send(res,401,'UNAUTHORIZED','Authentication is required.');const deleted=await realAuthRepository.deletePasskey(auth.user.id,req.params.passkeyId);if(!deleted)return send(res,404,'PASSKEY_NOT_FOUND','Passkey not found.');await audit(req,auth.user,'auth.passkey_deleted');res.status(204).end();}catch{send(res,400,'PASSKEY_DELETE_FAILED','Unable to remove passkey.');}});

// Management
function requireManagement(req:AuthRequest,res:Response):boolean{if(!req.user||!['owner','admin','developer','service'].includes(req.user.role)){send(res,403,'FORBIDDEN','Management access is required.');return false;}if(req.projectId!==req.params.projectId||req.environmentId!==req.params.environmentId){send(res,403,'FORBIDDEN','Requested resource is outside the authenticated scope.');return false;}return true;}
realAuthRouter.get('/api/projects/:projectId/environments/:environmentId/auth/users',async(req:AuthRequest,res)=>{if(!requireManagement(req,res))return;res.json(await realAuthRepository.listUsers(req.params.projectId,req.params.environmentId,String(req.query.search||'')));});
realAuthRouter.post('/api/projects/:projectId/environments/:environmentId/auth/users',async(req:AuthRequest,res)=>{try{if(!requireManagement(req,res))return;if(!req.body?.email)return send(res,400,'INVALID_INPUT','email is required.');const settings=await realAuthRepository.settings(req.params.projectId,req.params.environmentId);if(req.body.password){const e=passwordError(String(req.body.password),settings);if(e)return send(res,400,'WEAK_PASSWORD',e);}const user=await realAuthRepository.createUser({project_id:req.params.projectId,environment_id:req.params.environmentId,email:req.body.email,email_verified:req.body.email_verified!==false,display_name:req.body.name||String(req.body.email).split('@')[0],password_hash:req.body.password?await hashPasswordAsync(req.body.password):undefined,role:req.body.role||'user',status:req.body.status||'active',provider:req.body.provider||'email',user_metadata:req.body.user_metadata||{},app_metadata:req.body.app_metadata||{},custom_claims:req.body.custom_claims||{}});await realAuthRepository.createIdentity({user_id:user.id,project_id:user.project_id,environment_id:user.environment_id,provider:user.provider,provider_user_id:user.id,provider_email:user.email});res.status(201).json(publicUser(user));}catch{send(res,400,'CREATE_FAILED','Unable to create user.');}});
realAuthRouter.patch('/api/projects/:projectId/environments/:environmentId/auth/users/:userId/status',async(req:AuthRequest,res)=>{if(!requireManagement(req,res))return;if(!['active','disabled','banned','pending'].includes(String(req.body?.status)))return send(res,400,'INVALID_STATUS','Invalid user status.');const user=await realAuthRepository.updateUserInScope(req.params.projectId,req.params.environmentId,req.params.userId,{status:req.body.status});if(!user)return send(res,404,'USER_NOT_FOUND','User not found.');if(user.status!=='active')await realAuthRepository.revokeUserSessions(user.id);res.json(publicUser(user));});
realAuthRouter.patch('/api/projects/:projectId/environments/:environmentId/auth/users/:userId/authorization',async(req:AuthRequest,res)=>{if(!requireManagement(req,res))return;const role=String(req.body?.role||'user').trim();if(!/^[a-z][a-z0-9_-]{0,63}$/i.test(role)||!await roleAllowed(req.params.projectId,req.params.environmentId,role))return send(res,400,'INVALID_ROLE','Role must be built-in or created in this project/environment.');const claims=req.body?.claims||{};if(!validClaimsObject(claims))return send(res,400,'INVALID_CLAIMS','Claims must be a JSON object up to 8 KiB.');const user=await realAuthRepository.setUserAuthorization(req.params.projectId,req.params.environmentId,req.params.userId,role,claims);if(!user)return send(res,404,'USER_NOT_FOUND','User not found.');await realAuthRepository.revokeUserSessions(user.id);res.json(publicUser(user));});
realAuthRouter.delete('/api/projects/:projectId/environments/:environmentId/auth/users/:userId',async(req:AuthRequest,res)=>{if(!requireManagement(req,res))return;const user=await realAuthRepository.findUserById(req.params.userId);if(user&&(user.project_id!==req.params.projectId||user.environment_id!==req.params.environmentId))return res.status(404).end();const deleted=await realAuthRepository.deleteUserInScope(req.params.projectId,req.params.environmentId,req.params.userId);if(deleted&&user)await emitAuthWebhook(user,'auth.user.deleted');res.status(deleted?204:404).end();});
realAuthRouter.get('/api/projects/:projectId/environments/:environmentId/auth/sessions',async(req:AuthRequest,res)=>{if(!requireManagement(req,res))return;res.json(await realAuthRepository.listSessions(req.params.projectId,req.params.environmentId));});
realAuthRouter.post('/api/projects/:projectId/environments/:environmentId/auth/sessions/:sessionId/revoke',async(req:AuthRequest,res)=>{if(!requireManagement(req,res))return;const revoked=await realAuthRepository.revokeSessionInScope(req.params.projectId,req.params.environmentId,req.params.sessionId);if(!revoked)return send(res,404,'SESSION_NOT_FOUND','Session not found.');res.json({message:'Session revoked.'});});
realAuthRouter.get('/api/projects/:projectId/environments/:environmentId/auth/settings',async(req:AuthRequest,res)=>{if(!requireManagement(req,res))return;res.json(await realAuthRepository.settings(req.params.projectId,req.params.environmentId));});
realAuthRouter.patch('/api/projects/:projectId/environments/:environmentId/auth/settings',async(req:AuthRequest,res)=>{if(!requireManagement(req,res))return;const updates={...req.body};const validation=validateSettingsUpdate(updates);if(validation)return send(res,400,'INVALID_SETTINGS',validation);res.json(await realAuthRepository.updateSettings(req.params.projectId,req.params.environmentId,updates));});
realAuthRouter.get('/api/projects/:projectId/environments/:environmentId/auth/roles',async(req:AuthRequest,res)=>{if(!requireManagement(req,res))return;res.json(await realAuthRepository.listRoles(req.params.projectId,req.params.environmentId));});
realAuthRouter.put('/api/projects/:projectId/environments/:environmentId/auth/roles/:role',async(req:AuthRequest,res)=>{if(!requireManagement(req,res))return;const name=req.params.role.trim();if(!/^[a-z][a-z0-9_-]{0,63}$/i.test(name)||['user','admin','moderator','authenticated','anonymous'].includes(name))return send(res,400,'INVALID_ROLE','Custom role name is invalid or reserved.');const claims=req.body?.claims||{};if(!validClaimsObject(claims))return send(res,400,'INVALID_CLAIMS','Claims must be a JSON object up to 8 KiB.');res.json(await realAuthRepository.upsertRole(req.params.projectId,req.params.environmentId,name,String(req.body?.description||'').slice(0,1000),claims));});
realAuthRouter.delete('/api/projects/:projectId/environments/:environmentId/auth/roles/:role',async(req:AuthRequest,res)=>{if(!requireManagement(req,res))return;if(['user','admin','moderator','authenticated','anonymous'].includes(req.params.role))return send(res,400,'BUILTIN_ROLE','Built-in roles cannot be deleted.');if(await realAuthRepository.countUsersByRole(req.params.projectId,req.params.environmentId,req.params.role))return send(res,409,'ROLE_IN_USE','Move users to another role before deleting it.');const deleted=await realAuthRepository.deleteRole(req.params.projectId,req.params.environmentId,req.params.role);res.status(deleted?204:404).end();});

realAuthRouter.get('/api/projects/:projectId/environments/:environmentId/auth/providers',async(req:AuthRequest,res)=>{if(!requireManagement(req,res))return;res.json((await realAuthRepository.listProviderConfigs(req.params.projectId,req.params.environmentId)).map(publicProvider));});
realAuthRouter.patch('/api/projects/:projectId/environments/:environmentId/auth/providers/:providerId',async(req:AuthRequest,res)=>{if(!requireManagement(req,res))return;const{projectId,environmentId,providerId}=req.params;const current=await realAuthRepository.getProviderConfig(projectId,environmentId,providerId);if(!current)return send(res,404,'PROVIDER_NOT_FOUND','OAuth provider not found.');const clientId=typeof req.body?.clientId==='string'?req.body.clientId.trim():undefined;const clientSecret=typeof req.body?.clientSecret==='string'?req.body.clientSecret:undefined;const enabled=typeof req.body?.enabled==='boolean'?req.body.enabled:undefined;const nextClientId=clientId===undefined?current.client_id:clientId;const nextSecret=clientSecret?true:Boolean(current.client_secret_encrypted);if(enabled&&providerId!=='email'&&(!nextClientId||!nextSecret))return send(res,400,'OAUTH_NOT_CONFIGURED','Configure a client ID and secret before enabling this provider.');const updated=await realAuthRepository.updateProviderConfig(projectId,environmentId,providerId,{...(enabled===undefined?{}:{enabled}),...(clientId===undefined?{}:{client_id:clientId}),...(clientSecret?{client_secret_encrypted:encryptSecret(clientSecret)}:{})});res.json(publicProvider(updated));});

// OAuth providers
async function oauthSettings(provider:string,projectId:string,environmentId:string):Promise<{clientId?:string;clientSecret?:string;redirectUri?:string}>{const configured=await realAuthRepository.getProviderConfig(projectId,environmentId,provider);if(!configured?.enabled||!configured.client_id||!configured.client_secret_encrypted||!configured.redirect_url)return{};return{clientId:configured.client_id,clientSecret:decryptSecret(configured.client_secret_encrypted),redirectUri:configured.redirect_url};}
const OAUTH_STATE_COOKIE='brisabase_oauth_state';function oauthCookieOptions(){return{httpOnly:true,secure:config.cookies.secure,sameSite:'lax' as const,domain:config.cookies.domain,path:'/api/auth/oauth',maxAge:10*60*1000};}
realAuthRouter.get('/api/auth/oauth/:provider/link',async(req,res)=>{try{const auth=await authUserFromToken(bearer(req));if(!auth)return send(res,401,'UNAUTHORIZED','Authentication is required to link an OAuth identity.');const oauth=await oauthSettings(req.params.provider,auth.user.project_id,auth.user.environment_id);if(!oauth.clientId||!oauth.clientSecret||!oauth.redirectUri)return send(res,501,'OAUTH_NOT_CONFIGURED','OAuth provider not configured.');const authSettings=await realAuthRepository.settings(auth.user.project_id,auth.user.environment_id);const state=generateRandomToken(32);await redisClient.set(`oauth:state:${hashToken(state)}`,{projectId:auth.user.project_id,environmentId:auth.user.environment_id,redirectUrl:normalizedRedirect(req.query.redirect_url,authSettings),provider:req.params.provider,linkUserId:auth.user.id,linkSessionId:auth.payload.session_id},600);res.cookie(OAUTH_STATE_COOKIE,state,oauthCookieOptions());res.json({authorization_url:await getOAuthProvider(req.params.provider,oauth.clientId,oauth.clientSecret).getAuthorizationUrl(state,oauth.redirectUri)});}catch{send(res,400,'OAUTH_LINK_ERROR','Unable to start OAuth identity linking.');}});
realAuthRouter.get('/api/auth/oauth/:provider',async(req,res)=>{try{const projectId=String(req.query.project_id||req.headers['x-project-id']||'');const environmentId=String(req.query.environment_id||req.headers['x-environment-id']||'');if(!projectId||!environmentId)return send(res,400,'INVALID_INPUT','project_id and environment_id are required.');if(!await validScope({projectId,environmentId}))return send(res,400,'INVALID_SCOPE','OAuth project scope is invalid.');const oauth=await oauthSettings(req.params.provider,projectId,environmentId);if(!oauth.clientId||!oauth.clientSecret||!oauth.redirectUri)return send(res,501,'OAUTH_NOT_CONFIGURED','OAuth provider not configured.');const authSettings=await realAuthRepository.settings(projectId,environmentId);const state=generateRandomToken(32);await redisClient.set(`oauth:state:${hashToken(state)}`,{projectId,environmentId,redirectUrl:normalizedRedirect(req.query.redirect_url,authSettings),provider:req.params.provider},600);res.cookie(OAUTH_STATE_COOKIE,state,oauthCookieOptions());res.redirect(await getOAuthProvider(req.params.provider,oauth.clientId,oauth.clientSecret).getAuthorizationUrl(state,oauth.redirectUri));}catch{send(res,400,'OAUTH_ERROR','Unable to start OAuth authentication.');}});
realAuthRouter.get('/api/auth/oauth/:provider/callback',async(req,res)=>{try{const opaque=String(req.query.state||'');const stateCookie=readCookie(req,OAUTH_STATE_COOKIE);if(!opaque||!stateCookie||hashToken(opaque)!==hashToken(stateCookie))return send(res,400,'INVALID_INPUT','OAuth callback is not bound to the initiating browser session.');const state=await redisClient.get<any>(`oauth:state:${hashToken(opaque)}`);if(!state||state.provider!==req.params.provider||!req.query.code)return send(res,400,'INVALID_INPUT','Invalid or expired OAuth callback state.');await redisClient.del(`oauth:state:${hashToken(opaque)}`);res.clearCookie(OAUTH_STATE_COOKIE,{...oauthCookieOptions(),maxAge:undefined});const oauth=await oauthSettings(req.params.provider,state.projectId,state.environmentId);if(!oauth.clientId||!oauth.clientSecret||!oauth.redirectUri)return send(res,501,'OAUTH_NOT_CONFIGURED','OAuth provider not configured.');const identity=await getOAuthProvider(req.params.provider,oauth.clientId,oauth.clientSecret).handleCallback(String(req.query.code),oauth.redirectUri);if(!identity.emailVerified)return send(res,403,'OAUTH_EMAIL_UNVERIFIED','OAuth provider did not verify the email address.');let link=await realAuthRepository.findIdentity(state.projectId,state.environmentId,req.params.provider,identity.providerUserId);let user=link?await realAuthRepository.findUserById(link.user_id):null;const settings=await realAuthRepository.settings(state.projectId,state.environmentId);if(state.linkUserId){const [actor,linkSession]=await Promise.all([realAuthRepository.findUserById(String(state.linkUserId)),realAuthRepository.findSession(String(state.linkSessionId||''))]);if(!actor||!linkSession||linkSession.user_id!==actor.id||actor.project_id!==state.projectId||actor.environment_id!==state.environmentId)return send(res,400,'OAUTH_LINK_INVALID','Linking session is invalid.');if(link&&link.user_id!==actor.id)return send(res,409,'OAUTH_IDENTITY_IN_USE','This OAuth identity is already linked to another account.');await realAuthRepository.createIdentity({user_id:actor.id,project_id:actor.project_id,environment_id:actor.environment_id,provider:req.params.provider,provider_user_id:identity.providerUserId,provider_email:identity.email,metadata:identity.metadata});await audit(req,actor,'auth.identity_linked',undefined,{provider:req.params.provider});return void res.json({linked:true,identity:{provider:req.params.provider,email:identity.email},redirect_url:state.redirectUrl||undefined});}if(!user){const sameEmail=await realAuthRepository.findUserByEmail(state.projectId,state.environmentId,identity.email);if(sameEmail)return send(res,409,'ACCOUNT_LINK_REQUIRED','An account already exists for this email. Sign in first and explicitly link this OAuth provider.');}if(!user&&!settings.allow_signups)return send(res,403,'SIGNUPS_DISABLED','New user registration is disabled.');let oauthUserCreated=false;if(!user){user=await realAuthRepository.createUser({project_id:state.projectId,environment_id:state.environmentId,email:identity.email,email_verified:true,display_name:identity.displayName,avatar_url:identity.avatarUrl,role:'user',status:'active',provider:req.params.provider,user_metadata:identity.metadata||{},app_metadata:{},custom_claims:{}});oauthUserCreated=true;}await realAuthRepository.createIdentity({user_id:user.id,project_id:user.project_id,environment_id:user.environment_id,provider:req.params.provider,provider_user_id:identity.providerUserId,provider_email:identity.email,metadata:identity.metadata});if(oauthUserCreated)await emitAuthWebhook(user,'auth.user.created',{method:req.params.provider});const factor=await realAuthRepository.getVerifiedMfaFactor(user.id);if((settings.require_mfa||factor)&&req.query.mfa_code){if(!factor||!verifyTotpCode(decryptSecret(factor.secret_encrypted),String(req.query.mfa_code)))return send(res,401,'INVALID_MFA_CODE','MFA code is invalid.');}else if(settings.require_mfa||factor){return void res.json({mfa_required:true,mfa_ticket:preauthTicket(user,factor?'mfa_challenge':'mfa_enroll'),user:publicUser(user),redirect_url:state.redirectUrl||undefined});}await audit(req,user,'auth.oauth_login',undefined,{provider:req.params.provider});res.json({user:publicUser(user),session:await issue(user,settings,req,res,req.params.provider),redirect_url:state.redirectUrl||undefined});}catch{send(res,400,'OAUTH_FAILED','OAuth authentication failed.');}});
